const nodes7 = require("./src/");

function getVarList(ip, rack, slot) {
  const s7endpoint = new nodes7.S7Endpoint({
    host: ip,
    rack,
    slot,
    port: 10002,
  });

  s7endpoint.once("connect", async () => {
    try {
      const allBlocksInfo = await s7endpoint.getModuleIdentification();
      console.log(allBlocksInfo);
    } catch (err) {
      console.error(err);
    } finally {
      s7endpoint.disconnect();
    }
  });

  s7endpoint.connect().catch(console.error);
}

const ip = "127.0.0.1";
const rack = 0;
const slot = 1;

getVarList(ip, rack, slot);

